import{_ as a,a as l,c as r,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"MySQL 练习与参考解答：查询、幂等、并发和恢复","description":"以可执行断言复习NULL、外连接、分页、事务所有权、并发扣减和备份恢复边界。","frontmatter":{"title":"MySQL 练习与参考解答：查询、幂等、并发和恢复","description":"以可执行断言复习NULL、外连接、分页、事务所有权、并发扣减和备份恢复边界。","showdocs":{"topics":[{"id":"mysql","title":"MySQL","link":"/topics/mysql/"}],"kind":"知识专题","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"MySQL 8.4 实践课程","summary":"以可执行断言复习NULL、外连接、分页、事务所有权、并发扣减和备份恢复边界。","status":"active","related":[{"title":"MySQL 操作与命令","link":"/middleware/mysql/plus/ecosystem/mysql-general-general","kind":"知识专题","scope":"general","audience":"general"},{"title":"MySQL 查询练习：筛选、NULL 与分页","link":"/middleware/mysql/query-exercises","kind":"应用实践","scope":"general","audience":"general"},{"title":"MySQL 查询语法与函数","link":"/middleware/mysql/plus/subjects/mysql-select-base","kind":"知识专题","scope":"general","audience":"general"},{"title":"MySQL 基础概念对照","link":"/middleware/mysql/plus/subjects/mysql-base","kind":"知识专题","scope":"general","audience":"general"},{"title":"MySQL 基础概念对照 · 字符集至其他类似的数据库","link":"/middleware/mysql/plus/subjects/mysql-base-part-02","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"MySQL 运维恢复与排错：备份、执行计划和锁等待","link":"/middleware/mysql/plus/practice/operations"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"MySQL 运维恢复与排错：备份、执行计划和锁等待","link":"/middleware/mysql/plus/practice/operations"},"next":false},"headers":[],"relativePath":"middleware/mysql/pro/review/review.md","filePath":"middleware/mysql/pro/review/review.md"}'),s={name:"middleware/mysql/pro/review/review.md"};function t(n,e,d,p,o,c){return l(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="mysql-练习与参考解答-查询、幂等、并发和恢复" tabindex="-1">MySQL 练习与参考解答：查询、幂等、并发和恢复 <a class="header-anchor" href="#mysql-练习与参考解答-查询、幂等、并发和恢复" aria-label="Permalink to &quot;MySQL 练习与参考解答：查询、幂等、并发和恢复&quot;">​</a></h1><p>本轮仅全文静态审计，未安装依赖、启动服务、连接数据库或执行任何示例。下文实测、RED/GREEN及平台结果均为此前历史证据；本轮修改后的脚本未运行，命令与输出作为学习步骤和预期保留。</p><h2 id="exercises" tabindex="-1">动手题与预期 <a class="header-anchor" href="#exercises" aria-label="Permalink to &quot;动手题与预期 {#exercises}&quot;">​</a></h2><p>前置：<a href="/middleware/mysql/plus/practice/application#run">完整库存CLI</a>。练习只操作inventory_lab实验数据，先读题再展开下一节，不先复制答案。题2新增商品后，若需原始两商品状态须重新初始化；题5先在专用实验库将pen重置为1，并使用新的请求ID。</p><ol><li>运行verify后，比较COUNT(*)和COUNT(note)，解释<code>WHERE note=NULL</code>为什么返回零行。预期两个商品但无已填note。</li><li>查询包括无预留商品在内的sku和预留数量，添加一个新商品后仍能显示它，预期该项为0。</li><li>说明按created_at分页为什么还要request_id，写出下一页条件。预期时间相同的记录不重复也不漏掉。</li><li>对book运行reserve review-1 book 1两次，再把同ID数量改成2。预期首次false、再次true、改参数失败，stock只少1。</li><li>将pen库存保持1，两个不同连接同时预留1，预期一胜一负，最终库存0，不能只看程序输出。</li><li>在UPDATE之后模拟异常，预期库存和预留数均保持原值；若连接已有事务，调用reserve应拒绝且保留调用方修改。</li><li>查看某sku按时间查询的EXPLAIN，指出选择索引与候选索引字段，不把估算行数当耗时。</li><li>导出并恢复到全新inventory_restore，核对中文emoji与数量。预期equal=true；目标已存在必须失败。</li></ol><h2 id="answers" tabindex="-1">参考解答与常见错误 <a class="header-anchor" href="#answers" aria-label="Permalink to &quot;参考解答与常见错误 {#answers}&quot;">​</a></h2><p>提示：查询题先写中间行集，事务题标出锁释放点与事务归属，恢复题区分导出时刻与比较时刻。</p><details><summary>展开参考解答</summary><p>题1：NULL比较是三值逻辑，用IS NULL；COUNT(note)不计NULL，COUNT(*)计行。不要用空字符串替换缺失值后再以COUNT推断业务填报率。</p><p>题2：<a href="/middleware/mysql/base/intermediate/model#queries">关联聚合</a>使用LEFT JOIN和COALESCE(SUM(r.quantity),0)，按p.sku,p.name分组。数量与请求数不同：2个商品的一次预留应SUM得2、COUNT请求得1。把关联表过滤条件放WHERE会删除无关联行，应按意图放ON。</p><p>题3：<code>WHERE (created_at,request_id)&gt;(%s,%s) ORDER BY created_at,request_id LIMIT 20</code>，参数来自上页尾行。唯一决胜键确定顺序；跨页并发变化仍需考虑一致性需求。</p><p>题4：产品锁后读取唯一request_id并比较sku/quantity，匹配直接提交并返回replayed=true；冲突抛错并回滚。只有请求ID相同不能证明业务相同。数据库主键不可替代参数一致性检查。</p><p>题5：<a href="/middleware/mysql/plus/practice/application#tests">verify.py</a>线程屏障启动两个独立连接，断言结果集合恰为reserved与insufficient stock，再查pen=0；SELECT FOR UPDATE持锁到事务结束。若把连接共享给两个线程，事务边界会混乱；若只验证最终库存可能遗漏重复预留。</p><p>题6：reserve异常路径显式rollback；测试fail_after_update=True确认stock和记录数不变。活跃事务必须在try前检查并拒绝，不能在start_transaction失败时回滚调用方先前修改；完整脚本有该回归断言。DDL不能靠普通ROLLBACK撤销。</p><p>题7：possible_keys为候选，key为实际选择；本实验key=ix_sku_created。rows是估算，EXPLAIN ANALYZE实际执行测行数与时间；两行小表结果不能推导生产容量。</p><p>题8：<a href="/middleware/mysql/plus/practice/application#backup-source">恢复脚本</a>明确utf8mb4、字节流导出导入，比较源/目标的排序行集合。仅比较文件大小、进程退出码或COUNT都不足以证明值和编码正确。保留dump哈希用于确认拿到同一份备份，哈希不能证明其内容业务正确。</p></details><h2 id="challenge" tabindex="-1">综合扩展与自检边界 <a class="header-anchor" href="#challenge" aria-label="Permalink to &quot;综合扩展与自检边界 {#challenge}&quot;">​</a></h2><p>独立实现“取消预留”：相同取消请求重放不重复加库存；未知请求报错；取消与新预留竞争仍保持数量守恒。先定义状态与唯一键，再写测试覆盖正常、重放、参数冲突、回滚与两个连接竞争，最后实现。参考设计是预留行增加状态并在同一事务中按固定顺序锁产品和预留，检查状态后加回库存并更新状态；不能先DELETE预留再无条件加库存。此扩展是练习，不算本批已交付功能。</p><p>能解释本项目为何不超卖，不等于掌握跨库分布式事务。后续主题包括复制/故障切换、binlog时间点恢复、在线DDL大表变更、分区与容量基准；未完成这些实测，不把首批课程标为MySQL所有运维能力完成。</p>',11)])])}const y=a(s,[["render",t]]);export{u as __pageData,y as default};
